function roleButtons(){ $('roleGrid').innerHTML=roles.map(r=>`<button class="role ${kind(r)} ${r===selectedRole?'selected':''}" data-role="${r}" aria-pressed="${r===selectedRole}">${r}</button>`).join('');$('roleType').textContent={tank:'TANK',healer:'HEALER',dps:'DPS'}[kind(selectedRole)];$('youRole').textContent=selectedRole;$('youRole').style.background={tank:'#23436a',healer:'#224436',dps:'#4c2a32'}[kind(selectedRole)];$('youRole').style.borderColor=colors[kind(selectedRole)];}
function me(){return party.find(p=>p.role===selectedRole)}
function required(){return mapping[me()?.clock??0]}
function phaseTime(){return Math.max(0,time-rep2At())}
