$('priorityRule').className=`priority-rule ${priority.group}`;$('priorityRule').textContent=known?`${priority.name} · depuis ${priority.startMark} · ${priority.label}${guide&&!staging()&&target?' · cible '+sourceMark(target):''}`:'Le repère de ton clone déterminera ta priorité.';
$('objectiveTitle').textContent=staging()||mode==='staging'?'Repère ton clone':phaseTime()<(mode==='links'?24:COMBAT.lock)?(goodLinks()?(required()==='none'?'Reste sans lien':'Garde ton lien'):'Récupère ton lien'):'Trouve ta position';
const own=ownedBy(),sameTypeWrong=own.length===1&&own[0].type===type&&!goodLinks();
$('objectiveCopy').textContent=mode==='staging'?'Le lien cyan relie ta pastille à ton clone joueur. Tu peux t’en approcher librement pour lire son repère. Ce mode sert uniquement au repérage.':staging()?'Le lien cyan relie ta pastille à ton clone joueur. Tu peux t’en approcher pour lire son repère, sans te placer dessus. Les liens de mécanique apparaîtront à la fin de ce court repérage.':type==='none'?'Ton clone est en C : ne prends aucun lien. Évite les liens étirés.':goodLinks()?'Tu portes le lien prioritaire. Reste juste sous sa source jusqu’au verrouillage.':sameTypeWrong?`Tu as le bon symbole, mais pas le premier clone : va prendre celui au repère ${sourceMark(target)}, en lisant depuis ${priority.startMark} en sens ${priority.label}.`:`${type==='boss'?'Ton clone est en A : prends le lien du boss.':`Depuis ${priority.startMark}, regarde en sens ${priority.label} et prends le premier clone ${types[type].name.toLowerCase()}.`} La cible reste la même même si tu possèdes déjà ce symbole. Récupération automatique au contact.`;
