canvas.addEventListener('pointerdown',e=>{if(!staging())return;const rect=canvas.getBoundingClientRect(),pos={x:((e.clientX-rect.left)/rect.width*1000-500)/arenaZoom(),y:((e.clientY-rect.top)/rect.height*1000-500)/arenaZoom()};const candidate=visibleClones().find(p=>dist(pos,pt(p.clock*TAU/8,325))<38);if(!candidate)return;selectedClock=candidate.clock;const correct=candidate.role===selectedRole;toast(correct?`✓ Ton clone est au repère ${marks[candidate.clock]}. Garde ce repère en mémoire.`:'Ce clone appartient à un autre joueur. Suis le lien de ta pastille.');updateObjective();record()});
function openModal(title,html){running=false;keys.clear();resetStick();updateUI();$('modalTitle').textContent=title;$('modalBody').innerHTML=html;$('modal').showModal()}
function strategy(){if(isDreamActive()){dreamStrategy();return}if(isCandyActive()){candyStrategy();return}if(isRep1Active()){rep1Strategy();return}openModal('Clone Zone / Caro · Priorités',`<p>Les huit clones joueurs et leurs liens d’attribution sont présents dès le départ. Repère le tien grâce au lien personnel : tu peux t’en approcher, sans te placer dessus. Aucun déplacement ni clic de confirmation n’est imposé. Son repère fixe la mécanique à récupérer et le sens de lecture. L’attribution reste aléatoire entre les huit rôles.</p><table><thead><tr><th>Clone joueur</th><th>Mécanique</th><th>Groupe / priorité</th></tr></thead><tbody>${marks.map((mark,clock)=>`<tr><td>${mark}</td><td>${types[mapping[clock]].name}</td><td>${clock===0?'Lien du boss':clock===4?'Aucun lien':priorityFor(clock).name+' · depuis '+priorityFor(clock).startMark+' · '+priorityFor(clock).label}</td></tr>`).join('')}</tbody></table><h3>La première source, même si tu as déjà le symbole</h3><p><b>Groupe A (A / 1 / B / 2)</b> : lis depuis A en sens horaire. <b>Groupe B (C / 3 / D / 4)</b> : lis depuis 4 en sens antihoraire. Pour ta mécanique, prends toujours le premier clone rencontré dans cet ordre. Ce choix ne dépend ni de ton lien actuel, ni du propriétaire de la source, ni de la distance depuis ta pastille.</p><p>Si tu possèdes déjà le même symbole mais venant de la seconde source, tu dois quand même rejoindre la première source. Les sept partenaires appliquent cette règle, puis restent sous leur source jusqu’au verrouillage. Le boss n’a aucun symbole ; A prend son lien et C reste sans lien.</p><div class="note">Les affectations, les deux groupes et les placements suivent tes schémas. Après les cônes, Snaking Kick vise un joueur aléatoire et fige sa direction pendant le cast. Passe derrière le boss. Reconstitution rejoue ensuite les clones par paires A/C → 1/3 → B/D → 2/4 ; Netherwrath annonce Proche ou Éloigné avant de cibler les deux joueurs les plus proches ou les plus éloignés.</div><h3>Après le verrouillage</h3><p>Les stacks et les cônes se placent à la limite nord dans l’ordre stack B, cône B, cône A, stack A. Le lien du boss se place sous A, les deux défamations sur les côtés et le joueur sans lien au sud. Firefall Splash saute sur son porteur, Scalding Waves cible les quatre autres joueurs les plus proches, puis Mana Burst frappe les deux liens de défamation et le joueur le plus éloigné.</p><p>Après les défamations, forme les light parties B et A pour les stacks. Les deux cônes suivent : les bots recherchent une orientation sans autre joueur dans le secteur, vers l’avant ou l’arrière. Les rayons, les défamations, les stacks et les cônes sont vérifiés par collision avec les positions réelles.</p><h3>Stacks de reconstitution</h3><p><b>Gauche / D : H1, H2, R1, R2.</b><br><b>Droite / B : MT, OT, M1, M2.</b><br>Ces groupes remplacent les groupes A/B uniquement pour les stacks clonés. La prise des liens, les premiers stacks et les duos Near/Far gardent leurs affectations précédentes.</p><h3>Référence</h3><a href="https://raidplan.io/plan/SFa6J6wDrU9PlCJ4" target="_blank" rel="noreferrer">Raidplan CJ4 ↗</a>`)}
function commands(){openModal('Les commandes',`<p><b>À toi d’abord</b> garde le chrono et les casts en continu. Les partenaires démarrent un peu après ton lien ou ton placement à chaque mécanique. Ils partent au plus tard quand il leur reste le temps de rejoindre leur position avant la résolution. <b>En groupe</b> garde le rythme continu. L’aide visuelle est indépendante ; désactive le mode guidé pour tester ta lecture sans réponse affichée.</p><p>Sur ordinateur, clique sur <b>Lancer l’entraînement</b>, puis utilise le clavier dans l’arène.</p><table><tr><td><kbd>Z Q S D</kbd> ou flèches</td><td>Déplacer la pastille de ton rôle</td></tr><tr><td>Contact automatique</td><td>Traverse un lien ou passe sur sa source pour le prendre. Aucun bouton n’est nécessaire. Plusieurs liens peuvent être pris : attention aux trajectoires.</td></tr><tr><td><kbd>Espace</kbd></td><td>Pause / reprendre</td></tr><tr><td><kbd>E</kbd> ou Provoquer</td><td>Candy Crush : prendre l’agro quand tu joues un tank. Le bouton est aussi utilisable sur mobile.</td></tr><tr><td><kbd>R</kbd></td><td>Recommencer le même tirage</td></tr><tr><td>Barre de replay</td><td>Revenir à un instant déjà joué, puis reprendre</td></tr></table><p>Dans l’atelier de placement, le cône suit ta dernière direction de déplacement. Le mode guidé affiche les clones compatibles et les positions cibles. Le bord de l’arène limite le déplacement.</p><p>Sur mobile, glisse le stick virtuel sous l’arène pour te déplacer. La prise des liens est automatique, comme au clavier. Le bouton ▶ / Ⅱ lance ou met en pause. Pendant les six secondes de repérage, les huit clones sont déjà présents et reliés à leur joueur. Tu peux t’approcher du tien ou toucher un clone pour annoter son repère. La suite commence automatiquement, sans contrôle de proximité. Les statistiques sont enregistrées dans ton navigateur. Les affectations suivent le schéma CJ4 fourni.</p>`)}
function notes(){openModal('À propos de cette version',`<h3>Idyllic Dream · Caro Uptime</h3><p>Les deux réalités, les liens ordonnés depuis A, les défamations NO/NE, les tours élémentaires et leur vulnérabilité lumière, les sauts de vent, les baits proche/loin, Temporal Curtain et les deux reconstitutions sont simulés. Timings BossMod et placements Caro Uptime recoupés avec le preset vérifié de Splatoon. L’apparence des tours et les animations sont reconstituées ; Esuna est automatique. La séquence s’arrête au raidwide de fin d’Idyllic, avant le dernier tankbuster et l’enrage.</p><p><b>Un prototype jouable pour apprendre à lire les liens.</b> Ce site n’est pas un replay importé de FFLogs et n’utilise aucun identifiant FFLogs.</p><h3>Ce qui est simulé</h3><p>Six clones du boss en hexagone (N, NE, SE, S, SO, NO), avec deux stacks, deux cônes et deux défamations ; le lien du boss sans symbole ; huit clones joueurs déjà présents au départ, avec leurs huit liens d’attribution et une affectation aléatoire ; prise et interception automatiques des liens au contact ; verrouillage et correction ; historique de déplacement et replay de l’essai.</p><h3>Rythmes d’entraînement</h3><p>« À toi d’abord » conserve le temps réel et décale le départ des bots à chaque mécanique. Ils attendent environ 0,7 seconde après ton lien ou ton placement, avec un départ limite adapté à leur trajet pour arriver avant la résolution. Le chrono, les casts et les attaques continuent pendant leur attente. Aucun bouton de validation n’est nécessaire. « En groupe » conserve la simulation continue. L’aide visuelle peut être activée ou masquée séparément.</p><h3>Fidélité de l’exercice</h3><p>Le tirage des symboles est un mélange pédagogique et ne reproduit pas encore les contraintes exactes des patterns en jeu. En rythme « En groupe », les sept partenaires s’approchent de leur clone joueur pendant le court repérage, puis rejoignent directement la première source de leur mécanique dans leur ordre de priorité (groupe A depuis A en horaire, groupe B depuis 4 en antihoraire), récupèrent leur lien et attendent dessous. Les liens ont un propriétaire persistant et peuvent être interceptés tant qu’ils ne sont pas verrouillés. Les distances de contact sont adaptées au simulateur. Les affectations et priorités de prise des liens suivent le schéma fourni : 1/4 cône, B/D stack, 2/3 défamation, A boss et C sans lien. Le saut, les rayons de proximité, les défamations agrandies, les stacks, les cônes, le cleave frontal figé, les quatre paires de clones et Netherwrath Near/Far sont simulés. Les intervalles des attaques principales et les durées des casts ont été recalés sur la timeline BossMod, recoupée avec Thaliak. Le repérage initial est fixé à six secondes pour l’entraînement. Les rayons et angles sont documentés dans « Chronologie & dimensions ». Les impacts de la reconstitution sont séparés : saut, défamations, stacks et cônes respectent leurs délais propres. Les animations et vitesses de déplacement restent illustratives. Les HP et les mitigations ne sont pas calculés. Replication 1 suit les vulnérabilités feu/ténèbres et applique automatiquement l’invulnérabilité du MT pour le premier Double Sobat.</p><div class="note">Les placements suivent les captures fournies. Le ciblage des quatre rayons et du joueur le plus éloigné est recoupé avec les guides ci-dessous. Les premiers stacks utilisent les groupes A et B issus des clones joueurs. Pour les stacks de la reconstitution, H1/H2/R1/R2 vont à gauche en D, tandis que MT/OT/M1/M2 vont à droite en B. Snaking Kick fige sa direction pendant le cast après avoir regardé un joueur aléatoire. Reconstitution rejoue les attaques réellement reçues : le clone A réutilise les mêmes cibles de rayons ; les autres clones rejouent leurs stacks, défamations ou cônes vers le centre. Netherwrath Near/Far est annoncé par le cast, puis cible les deux joueurs les plus proches ou les plus éloignés pour des partages à deux. Les bots appliquent cette répartition par rôle pour les stacks clonés, puis les joueurs de droite remontent au nord pour éviter la défamation en 2.</div><h3>Vidéo de référence</h3><p><a target="_blank" rel="noreferrer" href="https://www.youtube.com/watch?v=Osd---W8ZTY&t=339">Passage indiqué : 5:39–11:50 ↗</a><br>Lecture directe de la vidéo indisponible lors de cette mise à jour. L’atelier saute l’apparition des clones par paires et débute une fois les huit clones présents, à l’apparition de leurs liens d’attribution. Le repérage dure six secondes et ne requiert aucun passage sur le clone.</p><h3>Replication 1 · Static (7bz)</h3><p>Les premiers baits déterminent les débuffs réellement reçus. Après la division, le clone ténèbres extérieur définit le nouveau nord. Les positions Static sont recalées sur les coordonnées de Splatoon ; le ciblage et les rayons de 5 yalms (feu/ténèbres) et 10 yalms (tankbusters) suivent BossMod. Les positions des clones, animations de division et de saut restent des approximations à partir des captures. Le mode Combat complet conserve les transitions depuis le pull jusqu’à l’enrage. Les anciens enchaînements courts restent des exercices. Le télégraphe guidé du cleave Replication 2 apparaît après les cônes, même si le cast commence avant.</p><h3>Candy Crush · Blood Mana</h3><p>Débuffs alpha/bêta de 17 puis 28 secondes, transition de 2 secondes, candies mobiles ralentis au contact, ordre d’absorption, deux vagues à 5,1 secondes d’intervalle et partage Near/Far ciblé par la distance réelle. Les timings sont recalés sur le combat 30 du rapport FFLogs PcyCvGAFRqzrXJBj. Les vitesses et l’animation des candies sont des approximations. Provoquer : E ou bouton, uniquement pour le tank joué ; les bots le font automatiquement. L’OT bénéficie de l’invulnérabilité automatique pour son Double Sobat. Les soins et mitigations ne sont pas simulés.</p><h3>Sources mécaniques et timings</h3><p><a target="_blank" rel="noreferrer" href="https://github.com/awgil/ffxiv_bossmod/blob/master/BossMod.Modules/Dawntrail/Savage/RM12S2TheLindwurm/RM12S2TheLindwurmStates.cs">BossMod — chronologie Replication II</a></p><p><a target="_blank" rel="noreferrer" href="https://thaliak.com/raids/m12s2/">Thaliak — M12S phase 2</a><br><a target="_blank" rel="noreferrer" href="https://kitten-erp-guides.moe/savage/m12s/replication_2">Kitten ERP Guides — Replication 2</a><br><a target="_blank" rel="noreferrer" href="https://raidplan.io/plan/SFa6J6wDrU9PlCJ4">Raidplan CJ4 à confirmer</a></p><p>Fond d’arène reconstruit à partir de ta capture. Projet de fan non affilié à Square Enix ou FFLogs. FINAL FANTASY XIV © SQUARE ENIX.</p>`)}
$('strategyBtn').onclick=strategy;$('keysBtn').onclick=commands;$('helpBtn').onclick=commands;$('notesBtn').onclick=notes;$('trainingNav').onclick=()=>canvas.focus({preventScroll:true});$('closeModal').onclick=()=>$('modal').close();$('modal').addEventListener('click',e=>{if(e.target===$('modal')){const r=$('modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('modal').close()}});
// A small read-only snapshot supports reproducible browser QA without reaching outside the game.
window.cloneZone={snapshot:()=>({demoMode,encounter:cloneData(encounter),encounterTime:encounterClock(),feedback:cloneData(visibleFeedback()),role:selectedRole,required:required(),held:chosenType(),running,time,seed,staging:staging(),visiblePlayerClones:visibleClones().map(p=>({role:p.role,clock:p.clock})),attributionLinks:party.map(p=>attributionFor(p.role)),selectedClock,stick:{...stick},nearOwnClone:me().nearClone,party:party.map(p=>({...p})),sources:sources.map(s=>({id:s.id,type:s.type,x:s.x,y:s.y,owner:s.owner})),plannedSources:{...plannedSources},priority:{...priorityFor(me().clock)},linksActive,player:{...player},clones:clones.map(c=>({...c})),checks:{...checks},stats:{...stats},mode,trainingExercise,rep1:cloneData(rep1),rep1Scenario:cloneData(rep1Scenario),rep1Active:isRep1Active(),dreamActive:isDreamActive(),dream:cloneData(dream),dreamScenario:cloneData(dreamScenario),candyActive:isCandyActive(),candy:cloneData(candy),candyScenario:cloneData(candyScenario),partnerRhythm,decisions:cloneData(decisions),historyLength:history.length,resolution:cloneData(resolution)})};
